"""Материалы по Святилищу и Сырой темнице из отдельных исторических статей."""
from pathlib import Path
from io import BytesIO
import json,hashlib,requests
from PIL import Image
P=Path(__file__).resolve().parents[1]; cats=['buildings','materials','locations']; D={c:json.loads((P/'data'/f'{c}.json').read_text()) for c in cats}; I={(c,x['slug']):x for c,a in D.items() for x in a};base='https://zombie-island.moy.su/'
hashes={}
for f in (P/'img').rglob('*'):
 if f.is_file():hashes.setdefault(hashlib.sha256(f.read_bytes()).hexdigest(),str(f.relative_to(P)))
def image(slug,filepath,page,original_host=True):
 url=base+filepath; r=requests.get(url,timeout=25);r.raise_for_status();Image.open(BytesIO(r.content)).verify();h=hashlib.sha256(r.content).hexdigest();path=hashes.get(h)
 if not path:path=f'img/archive/sanctuary-winter-{slug}-{h[:12]}.png';(P/path).write_bytes(r.content);hashes[h]=path
 return {'path':path,'retrieved_from':url,'attribution':('http://zombicity.info/'+filepath if original_host else url),'source_page':base+page,'note':'Файл получен без перекодирования; авторство отдельно не установлено. Если в статье исходная ссылка ведёт на другой хост, побайтовое совпадение не проверено.'}
def add(cat,slug,name,page,pic,fields,typ='Постройка',same=True):
 if (cat,slug) in I:return
 x={'slug':slug,'name':name,'category':cat,'type':typ,'purchase':'нет данных','sale':'нет данных','obtain':'нет данных','use':'нет данных','features':'нет данных','versions':'историческая браузерная социальная игра; платформа и редакция уточняются','sources':[{'url':base+page,'label':'Zombie-island: отдельная историческая статья'}], 'image':image(slug,pic,page,same),'links':[],'event':'Святилище 2015 / Унесённые ветром 2016','original_category':typ,'prior_records':[{'original_id':'sanctuary-winter-'+slug,'original_category':typ,'version':'браузерная игра; платформа не уточнена','date':'дата публикации указана в URL, дата дальнейших правок неизвестна','fields':fields,'confidence':'Фанатский источник; возможны опечатки, поздние изменения и отличия платформ. Вероятности выпадения не установлены.'}]}
 D[cat].append(x);I[cat,slug]=x
def link(a,b,rel):
 if a not in I or b not in I:raise Exception((a,b))
 x=I[a];y=I[b]
 if not any(i.get('category')==b[0] and i.get('slug')==b[1] for i in x['links']):x['links'].append({'category':b[0],'slug':b[1],'name':y['name'],'relation':rel})
def extra(k,id,url,fields):
 x=I[k]
 if not any(t['url']==url for t in x['sources']):x['sources'].append({'url':url,'label':'Отдельная историческая статья Zombie-island'})
 if not any(t.get('original_id')==id for t in x.setdefault('prior_records',[])):x['prior_records'].append({'original_id':id,'original_category':'Историческая проверка','version':'браузерная социальная игра; платформа не уточнена','date':'дата статьи в URL; время поздних изменений неизвестно','fields':fields,'confidence':'Фанатские описания; цены и условия могли отличаться по версии или меняться.'})
